// Calculs déterministes : variation période/période, variation vs même période de l'année précédente (yoy),
// moyenne mobile 12 mois (mm12), tendance linéaire, franchissement de seuil.
// Les métriques yoy, mm12, seuil de matérialité et statut de validation sont requises par les règles
// d'interprétation RI2, RI4 et RI5 (§ 10.4.3 du rapport). Toute métrique non calculable est transmise
// à null : la couche d'interprétation doit alors signaler l'absence (RI0), pas conclure.
function trend(series){
  if (series.length < 2) return null;
  const n = series.length;
  const xs = series.map((_,i)=>i), ys = series.map(p=>p.value);
  const mx = xs.reduce((a,b)=>a+b,0)/n, my = ys.reduce((a,b)=>a+b,0)/n;
  const slope = xs.map((x,i)=>(x-mx)*(ys[i]-my)).reduce((a,b)=>a+b,0) / xs.map(x=>(x-mx)**2).reduce((a,b)=>a+b,0);
  return slope;
}
const out = [];
for (const item of $input.all()) {
  const s = item.json;
  const sorted = (s.points||[]).sort((a,b)=>a.period.localeCompare(b.period));
  const last = sorted[sorted.length-1], prev = sorted[sorted.length-2];
  const variation = (last && prev && prev.value) ? (last.value-prev.value)/prev.value*100 : null;
  let yoy = null;
  if (last && /^\d{4}-/.test(last.period)) {
    const refPeriod = String(Number(last.period.slice(0,4))-1) + last.period.slice(4);
    const ref = sorted.find(p=>p.period===refPeriod);
    if (ref && ref.value) yoy = (last.value-ref.value)/ref.value*100;
  }
  const mm12 = sorted.length >= 12 ? sorted.slice(-12).reduce((a,p)=>a+p.value,0)/12 : null;
  const threshold = s.alert_threshold_pct ?? 5;
  out.push({ json: { indicator_id: s.indicator_id, sector: s.sector, unit: s.unit,
    last_period: last?.period, last_value: last?.value,
    variation_pct: variation, yoy_pct: yoy, mm12: mm12,
    materiality_threshold_pct: threshold, validation_status: s.validation_status ?? null,
    n_points: sorted.length, slope: trend(sorted),
    breach: variation !== null && Math.abs(variation) >= threshold } });
}
return out;
